// getIdentifiersFromAssoc returns list of PodIdentifiers for given pod
func (c *WatchClient) getIdentifiersFromAssoc(pod *Pod) []PodIdentifier {
	var ids []PodIdentifier
	for _, assoc := range c.Associations {
		retID4containerID := -1
		ret := PodIdentifier{}
		skip := false
		for i, source := range assoc.Sources {
			// If association configured to take IP address from connection
			switch source.From {
			case ConnectionSource:
				if pod.Address == "" {
					skip = true
					break
				}
				// Host network mode is not supported right now with IP based
				// tagging as all pods in host network get same IP addresses.
				// Such pods are very rare and usually are used to monitor or control
				// host traffic (e.g, linkerd, flannel) instead of service business needs.
				if pod.HostNetwork {
					skip = true
					break
				}
				ret[i] = PodIdentifierAttributeFromSource(source, pod.Address)
			case ResourceSource:
				attr := ""
				switch source.Name {
				case string(conventions.K8SNamespaceNameKey):
					attr = pod.Namespace
				case string(conventions.K8SPodNameKey):
					attr = pod.Name
				case string(conventions.K8SPodUIDKey):
					attr = pod.PodUID
				case string(conventions.HostNameKey):
					attr = pod.Address
				// k8s.pod.ip is set by passthrough mode
				case string(conventions.K8SPodIPKey):
					attr = pod.Address
				case string(conventions.ContainerIDKey):
					// At this point just an empty attr is added and we remember the position.
					// Later this position in PodIdentifier will be filled with the actual
					// value for container.ID.
					retID4containerID = i
				default:
					if v, ok := pod.Attributes[source.Name]; ok {
						attr = v
					}
				}
				if attr == "" && retID4containerID == -1 {
					skip = true
					break
				}
				ret[i] = PodIdentifierAttributeFromSource(source, attr)
			}
		}

		if !skip {
			if retID4containerID != -1 {
				// As there can be multiple container.IDs per pod,
				// one PodIdentifier is added per container.ID.
				cIDs := maps.Keys(pod.Containers.ByID)
				for cID := range cIDs {
					retCpy := ret
					retCpy[retID4containerID] = PodIdentifierAttributeFromSource(AssociationSource{
						From: ResourceSource,
						Name: string(conventions.ContainerIDKey),
					}, cID)
					ids = append(ids, retCpy)
				}
			} else {
				ids = append(ids, ret)
			}
		}
	}

	// Ensure backward compatibility
	if pod.PodUID != "" {
		ids = append(ids, PodIdentifier{
			PodIdentifierAttributeFromResourceAttribute(string(conventions.K8SPodUIDKey), pod.PodUID),
		})
	}

	if pod.Address != "" && !pod.HostNetwork {
		ids = append(ids,
			PodIdentifier{
				PodIdentifierAttributeFromConnection(pod.Address),
			},
			// k8s.pod.ip is set by passthrough mode
			PodIdentifier{
				PodIdentifierAttributeFromResourceAttribute(string(conventions.K8SPodIPKey), pod.Address),
			})
	}

	return ids
}

func (c *WatchClient) addOrUpdatePod(pod *api_v1.Pod) {
	newPod := c.podFromAPI(pod)
	identifiers := c.getIdentifiersFromAssoc(newPod)
	var staleContainerIDRequests []deleteRequest

	c.m.Lock()
	var oldPod *Pod
	if newPod.PodUID != "" {
		if op, ok := c.Pods[podUIDIdentifier(newPod.PodUID)]; ok && op.PodUID == newPod.PodUID {
			oldPod = op
		}
	}
	for i := range identifiers {
		id := identifiers[i]
		// compare initial scheduled timestamp for existing pod and new pod with same identifier
		// and only replace old pod if scheduled time of new pod is newer or equal.
		// This should fix the case where scheduler has assigned the same attributes (like IP address)
		// to a new pod but update event for the old pod came in later.
		if p, ok := c.Pods[id]; ok {
			if pod.Status.StartTime.Before(p.StartTime) {
				continue
			}
		}
		c.Pods[id] = newPod
	}
	if c.hasContainerIDAssociation && oldPod != nil &&
		c.Pods[podUIDIdentifier(newPod.PodUID)] == newPod {
		// Run stale container.id cleanup only when this watch actually replaced the pod under
		// k8s.pod.uid. The loop skips c.Pods[uid]=newPod when pod.Status.StartTime is older than
		// the StartTime already stored for that key, so a stale watch leaves the UID entry
		// pointing at the previous *Pod.
		//
		// Only container.id-based identifiers are handled here.
		// Other identifiers can disappear and later reappear, so they need separate handling to preserve the grace period.
		// see https://github.com/open-telemetry/opentelemetry-collector-contrib/issues/48588
		staleContainerIDRequests = c.staleContainerIDDeleteRequestsLocked(oldPod, newPod)
	}
	c.m.Unlock()

	c.appendDeleteRequests(staleContainerIDRequests)
}

func (c *WatchClient) forgetPod(pod *api_v1.Pod) {
	// Look up the cached pod using its UID. Unlike dynamic status attributes (such as IP addresses)
	// which may be cleared or missing in the final DELETE event payload, the Pod UID is immutable
	// and guaranteed to be present. Using the cached pod ensures we generate and clean up all keys
	// under which the pod was originally registered.
	uidKey := PodIdentifier{
		PodIdentifierAttributeFromResourceAttribute(string(conventions.K8SPodUIDKey), string(pod.UID)),
	}
	c.m.RLock()
	cachedPod, ok := c.Pods[uidKey]
	c.m.RUnlock()

	var identifiers []PodIdentifier
	if ok {
		identifiers = c.getIdentifiersFromAssoc(cachedPod)
	} else {
		// Fallback: if the pod was never added to the cache (e.g. startup/informer sync edge cases),
		// generate deletion keys from the incoming delete event payload directly.
		podToRemove := c.podFromAPI(pod)
		identifiers = c.getIdentifiersFromAssoc(podToRemove)
	}

	for i := range identifiers {
		id := identifiers[i]
		p, ok := c.GetPod(id)

		if ok && p.PodUID == string(pod.UID) {
			c.appendDeleteQueue(id, p.PodUID)
		}
	}
}

func (c *WatchClient) staleContainerIDDeleteRequestsLocked(oldPod, newPod *Pod) []deleteRequest {
	staleContainerIDs := staleContainerIDs(oldPod, newPod)
	if len(staleContainerIDs) == 0 {
		return nil
	}

	identifiers := c.getIdentifiersFromAssoc(oldPod)
	requests := make([]deleteRequest, 0, len(staleContainerIDs))
	for i := range identifiers {
		id := identifiers[i]
		if !podIdentifierHasContainerID(id, staleContainerIDs) {
			continue
		}
		if p, ok := c.Pods[id]; ok && p.PodUID == oldPod.PodUID {
			requests = append(requests, deleteRequest{id: id, podUID: oldPod.PodUID})
		}
	}
	return requests
}

func staleContainerIDs(oldPod, newPod *Pod) map[string]struct{} {
	if oldPod == nil || newPod == nil || oldPod.PodUID == "" || oldPod.PodUID != newPod.PodUID {
		return nil
	}

	staleContainerIDs := map[string]struct{}{}
	for containerID := range oldPod.Containers.ByID {
		if containerID == "" {
			continue
		}
		if _, ok := newPod.Containers.ByID[containerID]; !ok {
			staleContainerIDs[containerID] = struct{}{}
		}
	}
	return staleContainerIDs
}

func podIdentifierHasContainerID(id PodIdentifier, containerIDs map[string]struct{}) bool {
	for i := range id {
		attr := id[i]
		if attr.Source.From == ResourceSource && attr.Source.Name == string(conventions.ContainerIDKey) {
			if _, ok := containerIDs[attr.Value]; ok {
				return true
			}
		}
	}
	return false
}

func hasContainerIDAssociation(associations []Association) bool {
	for _, assoc := range associations {
		for _, source := range assoc.Sources {
			if source.From == ResourceSource && source.Name == string(conventions.ContainerIDKey) {
				return true
			}
		}
	}
	return false
}

func podUIDIdentifier(podUID string) PodIdentifier {
	return PodIdentifier{
		PodIdentifierAttributeFromResourceAttribute(string(conventions.K8SPodUIDKey), podUID),
	}
}

func (c *WatchClient) appendDeleteRequests(requests []deleteRequest) {
	for i := range requests {
		c.appendDeleteQueue(requests[i].id, requests[i].podUID)
	}
}

func (c *WatchClient) appendDeleteQueue(podID PodIdentifier, podUID string) {
	c.deleteMut.Lock()
	c.deleteQueue = append(c.deleteQueue, deleteRequest{
		id:     podID,
		podUID: podUID,
		ts:     time.Now(),
	})
	c.deleteMut.Unlock()
}

func (c *WatchClient) shouldIgnorePod(pod *api_v1.Pod) bool {
	// Check if user requested the pod to be ignored through annotations
	if v, ok := pod.Annotations[ignoreAnnotation]; ok {
		if strings.ToLower(strings.TrimSpace(v)) == "true" {
			return true
		}
	}

	// Check if user requested the pod to be ignored through configuration
	for _, excludedPod := range c.Exclude.Pods {
		if excludedPod.Name.MatchString(pod.Name) {
			return true
		}
	}

	return false
}

var singleValueOperators = map[selection.Operator]int{
	selection.Equals:       1,
	selection.DoubleEquals: 1,
	selection.NotEquals:    1,
	selection.GreaterThan:  1,
	selection.LessThan:     1,
}

func selectorsFromFilters(filters Filters) (labels.Selector, fields.Selector, error) {
	labelSelector := labels.Everything()
	for _, f := range filters.Labels {
		if f.Op == selection.In || f.Op == selection.NotIn {
			return nil, nil, fmt.Errorf("label filters don't support operator: '%s'", f.Op)
		}

		var vals []string
		if _, ok := singleValueOperators[f.Op]; ok {
			vals = []string{f.Value}
		}

		r, err := labels.NewRequirement(f.Key, f.Op, vals)
		if err != nil {
			return nil, nil, err
		}
		labelSelector = labelSelector.Add(*r)
	}

	var selectors []fields.Selector
	for _, f := range filters.Fields {
		switch f.Op {
		case selection.Equals:
			selectors = append(selectors, fields.OneTermEqualSelector(f.Key, f.Value))
		case selection.NotEquals:
			selectors = append(selectors, fields.OneTermNotEqualSelector(f.Key, f.Value))
		default:
			return nil, nil, fmt.Errorf("field filters don't support operator: '%s'", f.Op)
		}
	}

	if filters.Node != "" {
		selectors = append(selectors, fields.OneTermEqualSelector(podNodeField, filters.Node))
	}
	return labelSelector, fields.AndSelectors(selectors...), nil
}

