// SPDX-License-Identifier: Apache-2.0

package kube

import (
 "fmt"
 "testing"
 "time"

 "github.com/stretchr/testify/assert"
 "github.com/stretchr/testify/require"
 "go.opentelemetry.io/collector/component/componenttest"
